import React from 'react';

import BGU from '@components/BGU';
import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { getOneProduct } from '../@services/products.service';
import { IProduct } from '../@types/products.types';
import { editProductInModalAsync } from '../components/ProductAddModal/productAddModalHelper';
import ProductOneStat from '../components/ProductOneStat';

const ProductOnePage: React.FC<{ id_product: number }> = ({ id_product }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [product, setProduct] = React.useState<IProduct>();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getOneProduct(id_product);
      setProduct(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!product) return <PohAlert variant={AlertVariant.Danger}>Has no product</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs
        data={[
          { href: '/products', text: 'Продукты' },
          { href: '/products/' + id_product, text: product.name, active: true },
        ]}
      />

      <PohContainer>
        <PohRow>
          <PohCol sm={10}>
            <h3>{product.name}</h3>

            <p>
              <BGU
                portion={round(100, 0)}
                energy={round(product.energy, 0)}
                protein={round(product.protein, 0)}
                fat={round(product.fat, 0)}
                carbohydrates={round(product.carbs, 0)}
                unit="в 100g"
                className="ms-auto"
              />
            </p>
          </PohCol>
          <PohCol sm={2} className="text-end">
            <PohButton
              variant={ButtonVariant.Success}
              size={ButtonSize.Small}
              onClick={async () => {
                const newItem = await editProductInModalAsync(product);
                notificationHelper.success('Сохранено');
                setProduct(newItem);
              }}
            >
              Редактировать
            </PohButton>
          </PohCol>
        </PohRow>
        <ProductOneStat id_product={id_product} />
      </PohContainer>
    </div>
  );
};

export default ProductOnePage;
